import React from 'react';
import { Award } from 'lucide-react';

const SlideContent = ({ slide, isActive }) => {
  return (
    <div
      className={`absolute inset-0 transition-opacity duration-1000 ${
        isActive ? 'opacity-100' : 'opacity-0'
      }`}
    >
      <div
        className="w-full h-full bg-cover bg-center"
        style={{ backgroundImage: `url(${slide.image})` }}
      >
        <div className="absolute inset-0 bg-black bg-opacity-40"></div>
      </div>
      
      {/* ISO Certified Badge */}
      <div className="absolute top-8 right-8 bg-white bg-opacity-95 rounded-lg shadow-lg px-6 py-4 flex items-center space-x-3">
        <Award className="w-8 h-8 text-[#5dade2]" />
        <div>
          <p className="text-xs font-semibold text-gray-600">QUALITY ASSURED</p>
          <p className="text-lg font-bold text-[#3d3d3d]">ISO CERTIFIED</p>
        </div>
      </div>
      
      {/* Slide Content */}
      <div className="absolute inset-0 flex flex-col items-center justify-center text-center">
        <h1 className="text-white text-5xl md:text-6xl font-light tracking-[0.3em] mb-8">
          {slide.title}
        </h1>
        <a
          href={slide.buttonLink || "tel:+919825814883"}
          className="bg-[#f4d03f] hover:bg-[#e6c230] text-black font-bold px-12 py-6 text-sm tracking-wider transition-all rounded inline-block"
        >
          {slide.buttonText}
        </a>
      </div>
    </div>
  );
};

export default SlideContent;
